package org.brightstats.stats;
import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
public final class CopulaChecks {
 private static int checks;
 private static void check(boolean value){if(!value)throw new AssertionError("Copula check "+checks);checks++;}
 private static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid copula input accepted");}catch(IllegalArgumentException expected){checks++;}}
 public static void main(String[] args)throws Exception{Path output=Path.of(args[0]);Files.createDirectories(output);Gson gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();JsonArray cases=new JsonArray();
 for(int scenario=0;scenario<7;scenario++){int n=160,p=scenario==3?4:2;double[][] x=new double[n][p];double[] y=new double[n];Random random=new Random(7463+scenario);for(int i=0;i<n;i++){double w=random.nextGaussian(),v=random.nextGaussian(),u=random.nextGaussian(),t=random.nextGaussian(),noise=random.nextGaussian(),zp=.6*w+.8*u;x[i][0]=scenario==4?zp:Math.exp(zp);x[i][1]=Math.exp(w);y[i]=1+1.7*x[i][0]-.6*x[i][1]+.7*u+.3*noise;if(scenario<2){x[i][0]=Math.exp(u);x[i][1]=w;y[i]=1+2*x[i][0]-.5*w+.7*u+.3*noise;}if(scenario==3){x[i][0]=Math.exp(.5*w+.2*v+Math.sqrt(.71)*u);x[i][1]=Math.sinh(.3*w-.4*v+Math.sqrt(.75)*t);x[i][2]=Math.exp(w);x[i][3]=Math.exp(.5*v);y[i]=.5+2*x[i][0]-x[i][1]+.3*x[i][2]+.2*x[i][3]+.5*u-.4*t+.3*noise;}if(scenario==5){x[i][0]=Math.rint(x[i][0]*10)/10;y[i]=1+1.7*x[i][0]-.6*x[i][1]+.7*u+.3*noise;}if(scenario==6){x[i][0]=Math.exp(u);x[i][1]=w>0?1:0;y[i]=2+1.5*x[i][0]-.7*x[i][1]+.5*u+.3*noise;}}
  var method=scenario<2||scenario==6?CopulaRegression.Method.ORIGINAL_GAUSSIAN:CopulaRegression.Method.TWO_STAGE_GAUSSIAN;var position=scenario%2==0?CopulaRegression.PlottingPosition.WEIBULL:CopulaRegression.PlottingPosition.HAZEN;var model=new CopulaRegression.Model(p==4?List.of("P1","P2","W1","W2"):List.of("P","W"),p==4?new int[]{0,1}:new int[]{0},method,position);var fit=CopulaRegression.fit(x,y,model);check(fit.observations()==n&&fit.coefficients().size()==p+1+model.endogenous().length);check(fit.generatedRegressors().length==n);check(fit.residualDegreesOfFreedom()==n-p-1-model.endogenous().length);check(fit.warnings().size()>=3);check(fit.standardizedConditionNumber()>1);double[][] generated=fit.generatedRegressors();double remembered=generated[0][0];generated[0][0]=999;check(fit.generatedRegressors()[0][0]==remembered);int[] indices=model.endogenous();indices[0]=99;check(model.endogenous()[0]==0);check(fit.coefficients().getLast().uncorrected()==null);JsonObject item=new JsonObject();item.addProperty("id","copula-"+scenario);item.add("predictors",gson.toJsonTree(x));item.add("response",gson.toJsonTree(y));item.add("model",gson.toJsonTree(model));item.add("fit",gson.toJsonTree(fit));
  if(scenario==0||scenario==2||scenario==3){var options=new Bootstrap.Options(80,42,.95,scenario==2?BootstrapIntervals.Method.BCA:BootstrapIntervals.Method.PERCENTILE,RegressionBootstrap.Convention.STANDARD,true);var result=CopulaRegression.bootstrap(x,y,model,options,null);check(result.inference().successful()==80&&result.inference().failed()==0);check(result.inference().estimates().size()==fit.coefficients().size());check(result.inference().signHandling().contains("recomputes midranks"));item.add("bootstrapOptions",gson.toJsonTree(options));item.add("bootstrap",gson.toJsonTree(result.inference()));if(scenario==0){var again=CopulaRegression.bootstrap(x,y,model,options,null);check(gson.toJson(result).equals(gson.toJson(again)));}}
  if(scenario==5)check(fit.diagnostics().getFirst().tiedObservations()>0);cases.add(item);
 }
 reject(()->new CopulaRegression.Model(List.of("P"),new int[]{0},CopulaRegression.Method.TWO_STAGE_GAUSSIAN,CopulaRegression.PlottingPosition.HAZEN));reject(()->new CopulaRegression.Model(List.of("P","P"),new int[]{0},CopulaRegression.Method.ORIGINAL_GAUSSIAN,CopulaRegression.PlottingPosition.HAZEN));for(int[] invalid:new int[][]{{},{-1},{2},{0,0}})reject(()->new CopulaRegression.Model(List.of("P","W"),invalid,CopulaRegression.Method.ORIGINAL_GAUSSIAN,CopulaRegression.PlottingPosition.HAZEN));var model=new CopulaRegression.Model(List.of("P"),new int[]{0},CopulaRegression.Method.ORIGINAL_GAUSSIAN,CopulaRegression.PlottingPosition.HAZEN);double[][] binary={{0},{1},{0},{1},{0},{1}},normal=new double[20][1];double[] response=new double[20];var distribution=new org.apache.commons.math3.distribution.NormalDistribution();for(int i=0;i<20;i++){normal[i][0]=distribution.inverseCumulativeProbability((i+.5)/20);response[i]=i+Math.sin(i);}reject(()->CopulaRegression.fit(binary,new double[]{1,2,3,4,5,6},model));for(String invalidIndex:new String[]{"0.5","\"0\"","null"}){try{org.brightstats.data.CopulaInput.index(JsonParser.parseString(invalidIndex));throw new AssertionError("Copula accepted noninteger schema index");}catch(IllegalArgumentException|ArithmeticException expected){checks++;}}reject(()->org.brightstats.data.CopulaInput.model(JsonParser.parseString("{\"names\":[1],\"endogenous\":[0]}")));reject(()->CopulaRegression.fit(normal,response,model));double[][] invalid={{1},{2},{3},{4},{Double.NaN},{6}};reject(()->CopulaRegression.fit(invalid,new double[]{1,2,3,4,5,6},model));reject(()->CopulaRegression.fit(new double[][]{{1},{2},{3}},new double[]{1,2,3},model));Thread.currentThread().interrupt();try{CopulaRegression.fit(normal,response,model);throw new AssertionError("Copula ignored cancellation");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}Files.writeString(output.resolve("cases.json"),gson.toJson(cases));Files.writeString(output.resolve("checks.json"),"{\"cases\":"+cases.size()+",\"checks\":"+checks+"}");System.out.println("{\"cases\":"+cases.size()+",\"checks\":"+checks+"}");
 }
}
